namespace DcxManager.Azure;

/// <summary>
/// The parts of Azure Resource Manager the app exposes (0.2.0; 0.4.0 added scale sets, availability sets, VM extensions,
/// network interfaces, private DNS, container instances, PostgreSQL / MySQL flexible servers, Resource Health and Advisor),
/// one screen per resource type, generated by the shared
/// cloud engine (ADR-020) like the other providers. Paths are subscription-scoped (<see cref="AzureClient.Sub"/>) and
/// carry their api-version; an item's own path is its resource id, filled with {path:id} (segment-escaped). Changes are
/// long-running in Azure; <see cref="AzureClient"/> follows each one to the end before the screen reports it. Read-only
/// accounts (the default) refuse every change before it is sent.
/// Not exposed (deliberately): access keys, connection strings and Key Vault secrets (the app never reads secrets out of
/// a cloud), the serial console (a WebSocket protocol the app has no client for) and anything a role assignment would
/// change (identity and access stay in the Azure portal).
/// </summary>
public static class AzureCatalog
{
    private const string Sub = AzureClient.Sub;
    private const string Rg = "2021-04-01", Compute = "2024-07-01", Disk = "2024-03-02", Net = "2024-05-01", Storage = "2023-05-01",
        Dns = "2018-05-01", Vault = "2023-07-01", Aks = "2024-09-01", Web = "2023-12-01", Sql = "2021-11-01",
        // 0.4.0 additions (DarkCipher0x: "include all features"): private DNS, flexible database servers, container instances, Advisor, Resource Health.
        PrivateDns = "2024-06-01", Postgres = "2024-08-01", MySql = "2023-12-30", Aci = "2023-05-01", Advisor = "2023-01-01", Health = "2022-10-01";

    public static readonly string[] GroupOrder = { "Compute", "Containers & apps", "Storage", "Network", "DNS", "Databases", "Security", "Resources", "Reference" };

    // ---- lookups ------------------------------------------------------------------------------------------------------
    public static readonly Lookup Locations = new($"/subscriptions/{Sub}/locations?api-version=2022-12-01", "value", "name", "displayName", "name");
    public static readonly Lookup ResourceGroups = new($"/subscriptions/{Sub}/resourcegroups?api-version={Rg}", "value", "name", "name", "location");

    private static string Item(string version) => "{path:id}?api-version=" + version;
    private static Col[] Common(params Col[] middle) => new Col[] { new("name", "Name", 170) }.Concat(middle).Concat(new Col[] { new("location", "Location", 90), new("_rg", "Resource group", 130) }).ToArray();
    private static ActionDef Post(string label, string verb, string version, string? confirm = null, bool danger = false, string? when = null, string? tip = null) =>
        new(label, "POST", "{path:id}/" + verb + "?api-version=" + version, Confirm: confirm, Danger: danger, When: when, Tip: tip);

