    public static readonly ResourceDef ResourceGroup = new()
    {
        Title = "Resource groups", Group = "Resources", Path = $"/subscriptions/{Sub}/resourcegroups?api-version={Rg}", Key = "value", NameField = "name", Icon = "▤",
        ItemPath = Item(Rg), TypeToDelete = true, CreateMethod = "PUT", CreatePath = $"/subscriptions/{Sub}/resourcegroups/{{form.name}}?api-version={Rg}",
        Description = "The subscription's resource groups. Deleting one deletes EVERYTHING in it.",
        Columns = new Col[] { new("name", "Name", 200), new("location", "Location", 100), new("properties.provisioningState", "State", 90), new("tags", "Tags", 200) },
        Create = new Field[] { new("name", "Name", Required: true, InPath: true, Hint: "letters, digits, - _ . ( )"), new("location", "Location", FieldKind.Lookup, true, Lookup: Locations), new("tags", "Tags (JSON)", FieldKind.Json, Default: "{}") },
        CreateConfirm = "Create the resource group “{form.name}”?",
    };

