        ItemPath = Item(version), TypeToDelete = true, StatusField = "properties.state",
        Description = $"{title.Replace(" (flexible)", "")} flexible servers: start, stop (storage still billed; Azure restarts a stopped server after 7 days) and restart. Logins and connection strings are never read.",
        Columns = Common(new("properties.state", "State", 80), new("properties.version", "Version", 60), new("sku.name", "SKU", 130), new("properties.storage.storageSizeGB", "Storage GB", 70), new("properties.fullyQualifiedDomainName", "Server", 230), new("properties.highAvailability.mode", "HA", 80)),
        Actions = new ActionDef[]
        {
            Post("▶ Start", "start", version, when: "Stopped"),
            Post("■ Stop", "stop", version, "Stop {name}? Its databases are unavailable until it is started (storage is still billed).", true, "Ready"),
            Post("↻ Restart", "restart", version, "Restart {name}? Connections drop for a short while.", false, "Ready"),
        },
    };
